-- Rôle des semaines après la refonte de la charge (9 langues). Rejouable.
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,8}', '{"fr": "Semaine allégée : blocs courts et une endurance TT. Tu récupères pour que ta nouvelle FTP en aéro s''exprime.", "en": "Lighter week: short blocks and one TT endurance ride. You recover so your new aero FTP can show.", "es": "Semana más ligera: bloques cortos y una resistencia en TT. Recuperas para que tu nueva FTP en aero se exprese.", "it": "Settimana di scarico: blocchi brevi e un endurance in TT. Recuperi perché la tua nuova FTP in aero si esprima.", "pt": "Semana mais leve: blocos curtos e um endurance em TT. Você recupera para que sua nova FTP em aero se expresse.", "de": "Entlastungswoche: kurze Blöcke und eine TT-Grundlageneinheit. Du erholst dich, damit deine neue FTP in Aero-Position zur Geltung kommt.", "nl": "Lichtere week: korte blokken en één duurtraining in TT. Je herstelt zodat je nieuwe FTP in aerohouding tot uiting komt.", "ja": "軽めの週：短いブロックとTTでのエンデュランス。回復して、エアロでの新しいFTPを発揮できるようにします。", "tr": "Hafif hafta: kısa bloklar ve bir TT dayanıklılık. Aero''daki yeni FTP''nin ortaya çıkması için toparlanıyorsun."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Mise en route : sweet spot 3×12'' et seuil 4×8'' en TT, une endurance TT entre les deux et une sortie longue.", "en": "Getting started: sweet spot 3×12'' and threshold 4×8'' in TT, with a TT endurance ride in between and a long ride.", "es": "Puesta en marcha: sweet spot 3×12'' y umbral 4×8'' en TT, con una resistencia en TT entre ambos y una salida larga.", "it": "Avvio: sweet spot 3×12'' e soglia 4×8'' in TT, un endurance in TT nel mezzo e un''uscita lunga.", "pt": "Início: sweet spot 3×12'' e limiar 4×8'' em TT, com um endurance em TT entre os dois e um treino longo.", "de": "Einstieg: Sweet Spot 3×12'' und Schwelle 4×8'' in TT, eine TT-Grundlageneinheit dazwischen und eine lange Fahrt.", "nl": "Instap: sweet spot 3×12'' en drempel 4×8'' in TT, met een duurtraining in TT ertussen en een lange rit.", "ja": "導入：TTでスイートスポット3×12''と閾値4×8''、間にTTでのエンデュランス、さらにロングライド。", "tr": "Başlangıç: TT''de sweet spot 3×12'' ve eşik 4×8'', arada bir TT dayanıklılık ve bir uzun sürüş."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "Sweet spot 3×15'' et premiers sur-sous, séparés par du tempo en TT : changer d''intensité sans bouger de position.", "en": "Sweet spot 3×15'' and first over-unders, separated by tempo in TT: changing intensity without moving out of position.", "es": "Sweet spot 3×15'' y primeros sobre-bajo, separados por tempo en TT: cambiar de intensidad sin moverte de la posición.", "it": "Sweet spot 3×15'' e primi sopra-sotto, separati da ritmo tempo in TT: cambiare intensità senza muoversi dalla posizione.", "pt": "Sweet spot 3×15'' e primeiros acima-abaixo, separados por ritmo tempo em TT: mudar de intensidade sem sair da posição.", "de": "Sweet Spot 3×15'' und erste Over-Under, getrennt durch Tempo in TT: die Intensität wechseln, ohne die Position zu verändern.", "nl": "Sweet spot 3×15'' en eerste over-unders, gescheiden door tempo in TT: van intensiteit wisselen zonder je houding te veranderen.", "ja": "スイートスポット3×15''と最初のオーバーアンダー、間にTTでのテンポ：ポジションを動かさずに強度を変えます。", "tr": "Sweet spot 3×15'' ve ilk üst-altlar, araya TT''de tempo: pozisyonu bozmadan yoğunluk değiştirmek."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Pic du premier cycle : 3×12'' au seuil, sur-sous et 5×4'' à la puissance critique, le tempo au milieu reste facile.", "en": "First-cycle peak: 3×12'' at threshold, over-unders and 5×4'' at critical power; the tempo in the middle stays easy.", "es": "Pico del primer ciclo: 3×12'' al umbral, sobre-bajo y 5×4'' a potencia crítica; el tempo en medio sigue siendo fácil.", "it": "Picco del primo ciclo: 3×12'' in soglia, sopra-sotto e 5×4'' alla potenza critica; il ritmo tempo nel mezzo resta facile.", "pt": "Pico do primeiro ciclo: 3×12'' no limiar, acima-abaixo e 5×4'' na potência crítica; o ritmo tempo no meio continua fácil.", "de": "Höhepunkt des ersten Zyklus: 3×12'' an der Schwelle, Over-Under und 5×4'' bei kritischer Leistung, das Tempo in der Mitte bleibt locker.", "nl": "Hoogtepunt van de eerste cyclus: 3×12'' op drempel, over-unders en 5×4'' op kritisch vermogen, het tempo ertussen blijft makkelijk.", "ja": "第1サイクルのピーク：閾値3×12''、オーバーアンダー、クリティカルパワー5×4''。真ん中のテンポは楽に保ちます。", "tr": "İlk döngünün zirvesi: eşikte 3×12'', üst-altlar ve kritik güçte 5×4'', ortadaki tempo kolay kalır."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : volume divisé par deux. C''est pendant cette semaine que la FTP monte.", "en": "Lighter week: volume halved. This is the week your FTP rises.", "es": "Semana más ligera: volumen a la mitad. Es durante esta semana cuando sube la FTP.", "it": "Settimana di scarico: volume dimezzato. È in questa settimana che la FTP sale.", "pt": "Semana mais leve: volume pela metade. É nesta semana que a FTP sobe.", "de": "Entlastung: Umfang halbiert. In dieser Woche steigt die FTP.", "nl": "Afbouw: volume gehalveerd. Tijdens deze week stijgt de FTP.", "ja": "軽めの週：ボリュームは半分。FTPが上がるのはこの週です。", "tr": "Hafifletme: hacim yarıya iniyor. FTP''nin yükseldiği hafta bu."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,5}', '{"fr": "Deuxième cycle : 3×20'' en sweet spot et 3×15'' au seuil, des blocs proches d''un CLM.", "en": "Second cycle: 3×20'' at sweet spot and 3×15'' at threshold, blocks close to a TT.", "es": "Segundo ciclo: 3×20'' en sweet spot y 3×15'' al umbral, bloques cercanos a una CRI.", "it": "Secondo ciclo: 3×20'' in sweet spot e 3×15'' in soglia, blocchi vicini a una crono.", "pt": "Segundo ciclo: 3×20'' em sweet spot e 3×15'' no limiar, blocos próximos de um contrarrelógio.", "de": "Zweiter Zyklus: 3×20'' im Sweet Spot und 3×15'' an der Schwelle, Blöcke nahe an einem Zeitfahren.", "nl": "Tweede cyclus: 3×20'' in sweet spot en 3×15'' op drempel, blokken dicht bij een tijdrit.", "ja": "第2サイクル：スイートスポット3×20''と閾値3×15''、タイムトライアルに近いブロック。", "tr": "İkinci döngü: sweet spot''ta 3×20'' ve eşikte 3×15'', bir zamana karşıya yakın bloklar."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "2×30'' en sweet spot et 4 séries de sur-sous : les efforts longs en TT font le plus progresser la FTP en aéro.", "en": "2×30'' at sweet spot and 4 sets of over-unders: long efforts in TT do the most to raise your aero FTP.", "es": "2×30'' en sweet spot y 4 series de sobre-bajo: los esfuerzos largos en TT son los que más hacen progresar la FTP en aero.", "it": "2×30'' in sweet spot e 4 serie di sopra-sotto: gli sforzi lunghi in TT sono quelli che fanno progredire di più la FTP in aero.", "pt": "2×30'' em sweet spot e 4 séries de acima-abaixo: os esforços longos em TT são os que mais fazem a FTP em aero progredir.", "de": "2×30'' im Sweet Spot und 4 Serien Over-Under: Lange Belastungen in TT bringen die FTP in Aero-Position am weitesten voran.", "nl": "2×30'' in sweet spot en 4 series over-unders: lange inspanningen in TT laten de FTP in aerohouding het meest vooruitgaan.", "ja": "スイートスポット2×30''とオーバーアンダー4セット：TTでの長い努力こそ、エアロでのFTPを最も伸ばします。", "tr": "Sweet spot''ta 2×30'' ve 4 set üst-alt: TT''deki uzun eforlar aero''daki FTP''yi en çok geliştirir."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,7}', '{"fr": "Pic du deuxième cycle : 3×20'' au seuil, 4×10 sur-sous et 6×5'' à 108 %.", "en": "Second-cycle peak: 3×20'' at threshold, 4×10 over-unders and 6×5'' at 108 %.", "es": "Pico del segundo ciclo: 3×20'' al umbral, 4×10 sobre-bajo y 6×5'' al 108 %.", "it": "Picco del secondo ciclo: 3×20'' in soglia, 4×10 sopra-sotto e 6×5'' al 108 %.", "pt": "Pico do segundo ciclo: 3×20'' no limiar, 4×10 acima-abaixo e 6×5'' a 108 %.", "de": "Höhepunkt des zweiten Zyklus: 3×20'' an der Schwelle, 4×10 Over-Under und 6×5'' bei 108 %.", "nl": "Hoogtepunt van de tweede cyclus: 3×20'' op drempel, 4×10 over-unders en 6×5'' op 108 %.", "ja": "第2サイクルのピーク：閾値3×20''、オーバーアンダー4×10、108 %で6×5''。", "tr": "İkinci döngünün zirvesi: eşikte 3×20'', 4×10 üst-alt ve %108''de 6×5''."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,8}', '{"fr": "Allègement avant le dernier cycle, blocs courts et une endurance TT.", "en": "Lighter week before the final cycle, short blocks and one TT endurance ride.", "es": "Semana más ligera antes del último ciclo, bloques cortos y una resistencia en TT.", "it": "Settimana di scarico prima dell''ultimo ciclo, blocchi brevi e un endurance in TT.", "pt": "Semana mais leve antes do último ciclo, blocos curtos e um endurance em TT.", "de": "Entlastung vor dem letzten Zyklus, kurze Blöcke und eine TT-Grundlageneinheit.", "nl": "Afbouw voor de laatste cyclus, korte blokken en één duurtraining in TT.", "ja": "最終サイクル前の軽めの週、短いブロックとTTでのエンデュランス。", "tr": "Son döngüden önce hafifletme, kısa bloklar ve bir TT dayanıklılık."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,9}', '{"fr": "Troisième cycle : 2×40'' en sweet spot et 2×25'' au seuil. La durée en TT dépasse celle de la plupart des CLM.", "en": "Third cycle: 2×40'' at sweet spot and 2×25'' at threshold. The time in TT exceeds that of most TTs.", "es": "Tercer ciclo: 2×40'' en sweet spot y 2×25'' al umbral. La duración en TT supera la de la mayoría de las CRI.", "it": "Terzo ciclo: 2×40'' in sweet spot e 2×25'' in soglia. La durata in TT supera quella della maggior parte delle crono.", "pt": "Terceiro ciclo: 2×40'' em sweet spot e 2×25'' no limiar. A duração em TT supera a da maioria dos contrarrelógios.", "de": "Dritter Zyklus: 2×40'' im Sweet Spot und 2×25'' an der Schwelle. Die Dauer in TT übertrifft die der meisten Zeitfahren.", "nl": "Derde cyclus: 2×40'' in sweet spot en 2×25'' op drempel. De duur in TT overtreft die van de meeste tijdritten.", "ja": "第3サイクル：スイートスポット2×40''と閾値2×25''。TTでの時間はほとんどのタイムトライアルを上回ります。", "tr": "Üçüncü döngü: sweet spot''ta 2×40'' ve eşikte 2×25''. TT''deki süre çoğu zamana karşı yarışını aşıyor."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,10}', '{"fr": "60'' d''affilée en sweet spot et 5 séries de sur-sous : la FTP se travaille sur des durées de course.", "en": "60'' straight at sweet spot and 5 sets of over-unders: FTP is trained over race durations.", "es": "60'' seguidos en sweet spot y 5 series de sobre-bajo: la FTP se trabaja en duraciones de carrera.", "it": "60'' di fila in sweet spot e 5 serie di sopra-sotto: la FTP si allena su durate di gara.", "pt": "60'' seguidos em sweet spot e 5 séries de acima-abaixo: a FTP se treina em durações de prova.", "de": "60'' am Stück im Sweet Spot und 5 Serien Over-Under: Die FTP wird über Renndauern trainiert.", "nl": "60'' aan één stuk in sweet spot en 5 series over-unders: de FTP train je over wedstrijdduren.", "ja": "スイートスポットで60''連続とオーバーアンダー5セット：FTPをレースの時間で鍛えます。", "tr": "Sweet spot''ta kesintisiz 60'' ve 5 set üst-alt: FTP yarış sürelerinde çalışılır."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,11}', '{"fr": "Pic du plan : 2×30'' au seuil, 5×10 sur-sous et 6×6'' à 108 %, avec une heure de tempo en TT au milieu.", "en": "Plan peak: 2×30'' at threshold, 5×10 over-unders and 6×6'' at 108 %, with an hour of tempo in TT in the middle.", "es": "Pico del plan: 2×30'' al umbral, 5×10 sobre-bajo y 6×6'' al 108 %, con una hora de tempo en TT en medio.", "it": "Picco del piano: 2×30'' in soglia, 5×10 sopra-sotto e 6×6'' al 108 %, con un''ora di ritmo tempo in TT nel mezzo.", "pt": "Pico do plano: 2×30'' no limiar, 5×10 acima-abaixo e 6×6'' a 108 %, com uma hora de ritmo tempo em TT no meio.", "de": "Höhepunkt des Plans: 2×30'' an der Schwelle, 5×10 Over-Under und 6×6'' bei 108 %, mit einer Stunde Tempo in TT in der Mitte.", "nl": "Hoogtepunt van het plan: 2×30'' op drempel, 5×10 over-unders en 6×6'' op 108 %, met een uur tempo in TT ertussen.", "ja": "プランのピーク：閾値2×30''、オーバーアンダー5×10、108 %で6×6''、真ん中にTTでのテンポ1時間。", "tr": "Planın zirvesi: eşikte 2×30'', 5×10 üst-alt ve %108''de 6×6'', ortada TT''de bir saat tempo."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,12}', '{"fr": "Semaine allégée : tu récupères pour que ta nouvelle FTP en aéro s''exprime.", "en": "Lighter week: you recover so your new aero FTP can show.", "es": "Semana más ligera: recuperas para que tu nueva FTP en aero se exprese.", "it": "Settimana di scarico: recuperi perché la tua nuova FTP in aero si esprima.", "pt": "Semana mais leve: você recupera para que sua nova FTP em aero se expresse.", "de": "Entlastungswoche: Du erholst dich, damit deine neue FTP in Aero-Position zur Geltung kommt.", "nl": "Lichtere week: je herstelt zodat je nieuwe FTP in aerohouding tot uiting komt.", "ja": "軽めの週：回復して、エアロでの新しいFTPを発揮できるようにします。", "tr": "Hafif hafta: aero''daki yeni FTP''nin ortaya çıkması için toparlanıyorsun."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Bases du CLM : seuil 4×8'' et une première simulation à l''allure CLM en 3×6'', séparés par une endurance TT, plus une sortie longue.", "en": "TT basics: threshold 4×8'' and a first simulation at TT race pace as 3×6'', separated by a TT endurance ride, plus a long ride.", "es": "Bases de la CRI: umbral 4×8'' y una primera simulación a ritmo de CRI en 3×6'', separados por una resistencia en TT, más una salida larga.", "it": "Basi della crono: soglia 4×8'' e una prima simulazione al ritmo crono in 3×6'', separati da un endurance in TT, più un''uscita lunga.", "pt": "Bases do contrarrelógio: limiar 4×8'' e uma primeira simulação no ritmo de contrarrelógio em 3×6'', separados por um endurance em TT, mais um treino longo.", "de": "Grundlagen des Zeitfahrens: Schwelle 4×8'' und eine erste Simulation im Zeitfahrtempo in 3×6'', getrennt durch eine TT-Grundlageneinheit, dazu eine lange Fahrt.", "nl": "Basis van de tijdrit: drempel 4×8'' en een eerste simulatie op tijdrittempo in 3×6'', gescheiden door een duurtraining in TT, plus een lange rit.", "ja": "タイムトライアルの基礎：閾値4×8''と、TTレースペースでの最初のシミュレーション3×6''、間にTTでのエンデュランス、さらにロングライド。", "tr": "Zamana karşının temelleri: eşik 4×8'' ve zamana karşı temposunda 3×6'' ilk simülasyon, araya bir TT dayanıklılık, ayrıca bir uzun sürüş."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "PMA 5×4'' et allure CLM en 3×8''. Les deux séances faciles en TT entretiennent l''endurance de position.", "en": "VO2max 5×4'' and TT race pace as 3×8''. The two easy sessions in TT maintain your position endurance.", "es": "VO2max 5×4'' y ritmo de CRI en 3×8''. Las dos sesiones fáciles en TT mantienen la resistencia en posición.", "it": "VO2max 5×4'' e ritmo crono in 3×8''. Le due sedute facili in TT mantengono la resistenza in posizione.", "pt": "VO2max 5×4'' e ritmo de contrarrelógio em 3×8''. As duas sessões fáceis em TT mantêm a resistência na posição.", "de": "VO2max 5×4'' und Zeitfahrtempo in 3×8''. Die beiden lockeren Einheiten in TT erhalten die Positionsausdauer.", "nl": "VO2max 5×4'' en tijdrittempo in 3×8''. De twee makkelijke trainingen in TT onderhouden het uithoudingsvermogen in houding.", "ja": "VO2max 5×4''とTTレースペース3×8''。TTでの2回の楽なセッションがポジションの持久力を維持します。", "tr": "VO2max 5×4'' ve zamana karşı temposunda 3×8''. TT''deki iki kolay antrenman pozisyon dayanıklılığını korur."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Semaine de pic : sweet spot 2×20'', allure CLM 2×12'' et PMA 5×5''. Seule semaine du cycle à 3 séances dures.", "en": "Peak week: sweet spot 2×20'', TT race pace 2×12'' and VO2max 5×5''. The only week of the cycle with 3 hard sessions.", "es": "Semana pico: sweet spot 2×20'', ritmo de CRI 2×12'' y VO2max 5×5''. Única semana del ciclo con 3 sesiones duras.", "it": "Settimana di picco: sweet spot 2×20'', ritmo crono 2×12'' e VO2max 5×5''. Unica settimana del ciclo con 3 sedute dure.", "pt": "Semana de pico: sweet spot 2×20'', ritmo de contrarrelógio 2×12'' e VO2max 5×5''. Única semana do ciclo com 3 sessões duras.", "de": "Spitzenwoche: Sweet Spot 2×20'', Zeitfahrtempo 2×12'' und VO2max 5×5''. Die einzige Woche des Zyklus mit 3 harten Einheiten.", "nl": "Piekweek: sweet spot 2×20'', tijdrittempo 2×12'' en VO2max 5×5''. De enige week van de cyclus met 3 zware trainingen.", "ja": "ピーク週：スイートスポット2×20''、TTレースペース2×12''、VO2max 5×5''。サイクルで唯一きついセッションが3回ある週です。", "tr": "Zirve haftası: sweet spot 2×20'', zamana karşı temposu 2×12'' ve VO2max 5×5''. Döngünün 3 zor antrenmanlı tek haftası."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : une séance en moins, blocs courts. La fraîcheur revient avant les simulations longues.", "en": "Lighter week: one session fewer, short blocks. Freshness returns before the long simulations.", "es": "Semana más ligera: una sesión menos, bloques cortos. La frescura vuelve antes de las simulaciones largas.", "it": "Settimana di scarico: una seduta in meno, blocchi brevi. La freschezza torna prima delle simulazioni lunghe.", "pt": "Semana mais leve: uma sessão a menos, blocos curtos. A disposição volta antes das simulações longas.", "de": "Entlastung: eine Einheit weniger, kurze Blöcke. Die Frische kehrt vor den langen Simulationen zurück.", "nl": "Afbouw: één training minder, korte blokken. De frisheid komt terug voor de lange simulaties.", "ja": "軽めの週：セッションを1回減らし、短いブロック。長いシミュレーションの前にフレッシュさを取り戻します。", "tr": "Hafifletme: bir antrenman eksik, kısa bloklar. Uzun simülasyonlardan önce tazelik geri geliyor."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,5}', '{"fr": "Deuxième cycle : 2×20'' au seuil et 2×15'' à l''allure CLM, une endurance TT entre les deux. On se rapproche de la durée d''une course de 10 à 20 km.", "en": "Second cycle: 2×20'' at threshold and 2×15'' at TT race pace, with a TT endurance ride in between. We move closer to the duration of a 10 to 20 km race.", "es": "Segundo ciclo: 2×20'' al umbral y 2×15'' a ritmo de CRI, con una resistencia en TT entre ambos. Nos acercamos a la duración de una carrera de 10 a 20 km.", "it": "Secondo ciclo: 2×20'' in soglia e 2×15'' al ritmo crono, un endurance in TT nel mezzo. Ci avviciniamo alla durata di una gara da 10 a 20 km.", "pt": "Segundo ciclo: 2×20'' no limiar e 2×15'' no ritmo de contrarrelógio, com um endurance em TT entre os dois. Nos aproximamos da duração de uma prova de 10 a 20 km.", "de": "Zweiter Zyklus: 2×20'' an der Schwelle und 2×15'' im Zeitfahrtempo, eine TT-Grundlageneinheit dazwischen. Wir nähern uns der Dauer eines Rennens über 10 bis 20 km.", "nl": "Tweede cyclus: 2×20'' op drempel en 2×15'' op tijdrittempo, met een duurtraining in TT ertussen. We komen dicht bij de duur van een wedstrijd van 10 tot 20 km.", "ja": "第2サイクル：閾値2×20''とTTレースペース2×15''、間にTTでのエンデュランス。10〜20 kmのレースの時間に近づきます。", "tr": "İkinci döngü: eşikte 2×20'' ve zamana karşı temposunda 2×15'', arada bir TT dayanıklılık. 10-20 km''lik bir yarışın süresine yaklaşıyoruz."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "PMA 6×4'' et première simulation d''un seul tenant : 20'' à l''allure CLM. Ne te relève pas quand la douleur monte.", "en": "VO2max 6×4'' and a first unbroken simulation: 20'' at TT race pace. Don''t sit up when the pain builds.", "es": "VO2max 6×4'' y primera simulación de un solo tirón: 20'' a ritmo de CRI. No te incorpores cuando suba el dolor.", "it": "VO2max 6×4'' e prima simulazione tutta d''un fiato: 20'' al ritmo crono. Non rialzarti quando il dolore sale.", "pt": "VO2max 6×4'' e primeira simulação sem pausa: 20'' no ritmo de contrarrelógio. Não se levante quando a dor aumentar.", "de": "VO2max 6×4'' und erste Simulation am Stück: 20'' im Zeitfahrtempo. Richte dich nicht auf, wenn der Schmerz steigt.", "nl": "VO2max 6×4'' en eerste simulatie aan één stuk: 20'' op tijdrittempo. Kom niet overeind als de pijn toeneemt.", "ja": "VO2max 6×4''と、初めての通しのシミュレーション：TTレースペースで20''。苦しくなっても上体を起こさないこと。", "tr": "VO2max 6×4'' ve ilk kesintisiz simülasyon: zamana karşı temposunda 20''. Acı arttığında doğrulma."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,7}', '{"fr": "Pic du plan : 3×15'' au seuil, 25'' d''affilée à 100 % FTP et puissance critique. C''est la répétition générale de la course.", "en": "Plan peak: 3×15'' at threshold, 25'' straight at 100 % FTP and critical power. This is the dress rehearsal for the race.", "es": "Pico del plan: 3×15'' al umbral, 25'' seguidos al 100 % FTP y potencia crítica. Es el ensayo general de la carrera.", "it": "Picco del piano: 3×15'' in soglia, 25'' di fila al 100 % FTP e potenza critica. È la prova generale della gara.", "pt": "Pico do plano: 3×15'' no limiar, 25'' seguidos a 100 % FTP e potência crítica. É o ensaio geral da prova.", "de": "Höhepunkt des Plans: 3×15'' an der Schwelle, 25'' am Stück bei 100 % FTP und kritische Leistung. Die Generalprobe für das Rennen.", "nl": "Hoogtepunt van het plan: 3×15'' op drempel, 25'' aan één stuk op 100 % FTP en kritisch vermogen. De generale repetitie van de wedstrijd.", "ja": "プランのピーク：閾値3×15''、FTPの100 %で25''連続、クリティカルパワー。レースのリハーサルです。", "tr": "Planın zirvesi: eşikte 3×15'', FTP''nin %100''ünde kesintisiz 25'' ve kritik güç. Yarışın genel provası bu."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,8}', '{"fr": "Affûtage : volume réduit, quelques efforts à l''allure de course pour garder le rythme. Tu arrives frais le jour du CLM.", "en": "Taper: reduced volume, a few efforts at race pace to keep the rhythm. You arrive fresh on TT day.", "es": "Puesta a punto: volumen reducido, algunos esfuerzos a ritmo de carrera para mantener el ritmo. Llegas fresco el día de la CRI.", "it": "Scarico: volume ridotto, qualche sforzo al ritmo gara per mantenere il ritmo. Arrivi fresco il giorno della crono.", "pt": "Polimento: volume reduzido, alguns esforços no ritmo de prova para manter o ritmo. Você chega descansado no dia do contrarrelógio.", "de": "Tapering: weniger Umfang, einige Belastungen im Wettkampftempo, um den Rhythmus zu halten. Du gehst frisch ins Zeitfahren.", "nl": "Taperen: minder volume, enkele inspanningen op wedstrijdtempo om het ritme te houden. Je komt fris aan de start van de tijdrit.", "ja": "調整（テーパー）：ボリュームを減らし、リズムを保つためにレースペースでの努力を少し。タイムトライアル当日はフレッシュな状態で臨みます。", "tr": "Yarış öncesi yük azaltma: azaltılmış hacim, ritmi korumak için yarış temposunda birkaç efor. Zamana karşı günü taze geliyorsun."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Bases : sweet spot 3×12'' et seuil 3×10'', une endurance TT entre les deux et une sortie longue. On construit les deux moteurs d''un CLM de 40 km.", "en": "Basics: sweet spot 3×12'' and threshold 3×10'', with a TT endurance ride in between and a long ride. We build the two engines of a 40 km TT.", "es": "Bases: sweet spot 3×12'' y umbral 3×10'', con una resistencia en TT entre ambos y una salida larga. Construimos los dos motores de una CRI de 40 km.", "it": "Basi: sweet spot 3×12'' e soglia 3×10'', un endurance in TT nel mezzo e un''uscita lunga. Costruiamo i due motori di una crono di 40 km.", "pt": "Bases: sweet spot 3×12'' e limiar 3×10'', com um endurance em TT entre os dois e um treino longo. Construímos os dois motores de um contrarrelógio de 40 km.", "de": "Grundlagen: Sweet Spot 3×12'' und Schwelle 3×10'', eine TT-Grundlageneinheit dazwischen und eine lange Fahrt. Wir bauen die beiden Motoren eines 40-km-Zeitfahrens auf.", "nl": "Basis: sweet spot 3×12'' en drempel 3×10'', met een duurtraining in TT ertussen en een lange rit. We bouwen de twee motoren van een tijdrit van 40 km op.", "ja": "基礎：スイートスポット3×12''と閾値3×10''、間にTTでのエンデュランス、さらにロングライド。40 kmのタイムトライアルの2つのエンジンを築きます。", "tr": "Temeller: sweet spot 3×12'' ve eşik 3×10'', arada bir TT dayanıklılık ve bir uzun sürüş. 40 km''lik bir zamana karşının iki motorunu inşa ediyoruz."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "PMA 5×4'' pour élever le plafond et seuil 3×12'' pour la puissance de course, séparés par une endurance TT.", "en": "VO2max 5×4'' to raise the ceiling and threshold 3×12'' for race power, separated by a TT endurance ride.", "es": "VO2max 5×4'' para elevar el techo y umbral 3×12'' para la potencia de carrera, separados por una resistencia en TT.", "it": "VO2max 5×4'' per alzare il tetto e soglia 3×12'' per la potenza di gara, separati da un endurance in TT.", "pt": "VO2max 5×4'' para elevar o teto e limiar 3×12'' para a potência de prova, separados por um endurance em TT.", "de": "VO2max 5×4'', um die Obergrenze anzuheben, und Schwelle 3×12'' für die Wettkampfleistung, getrennt durch eine TT-Grundlageneinheit.", "nl": "VO2max 5×4'' om het plafond te verhogen en drempel 3×12'' voor het wedstrijdvermogen, gescheiden door een duurtraining in TT.", "ja": "上限を引き上げるVO2max 5×4''と、レースのパワーのための閾値3×12''、間にTTでのエンデュランス。", "tr": "Tavanı yükseltmek için VO2max 5×4'' ve yarış gücü için eşik 3×12'', araya bir TT dayanıklılık."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Pic du premier cycle : sweet spot 2×20'', puissance critique et 3×15'' au seuil. Seule semaine du cycle à 3 séances dures.", "en": "First-cycle peak: sweet spot 2×20'', critical power and 3×15'' at threshold. The only week of the cycle with 3 hard sessions.", "es": "Pico del primer ciclo: sweet spot 2×20'', potencia crítica y 3×15'' al umbral. Única semana del ciclo con 3 sesiones duras.", "it": "Picco del primo ciclo: sweet spot 2×20'', potenza critica e 3×15'' in soglia. Unica settimana del ciclo con 3 sedute dure.", "pt": "Pico do primeiro ciclo: sweet spot 2×20'', potência crítica e 3×15'' no limiar. Única semana do ciclo com 3 sessões duras.", "de": "Höhepunkt des ersten Zyklus: Sweet Spot 2×20'', kritische Leistung und 3×15'' an der Schwelle. Die einzige Woche des Zyklus mit 3 harten Einheiten.", "nl": "Hoogtepunt van de eerste cyclus: sweet spot 2×20'', kritisch vermogen en 3×15'' op drempel. De enige week van de cyclus met 3 zware trainingen.", "ja": "第1サイクルのピーク：スイートスポット2×20''、クリティカルパワー、閾値3×15''。サイクルで唯一きついセッションが3回ある週です。", "tr": "İlk döngünün zirvesi: sweet spot 2×20'', kritik güç ve eşikte 3×15''. Döngünün 3 zor antrenmanlı tek haftası."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : volume réduit, intensité conservée sur des blocs courts.", "en": "Lighter week: reduced volume, intensity kept on short blocks.", "es": "Semana más ligera: volumen reducido, intensidad mantenida en bloques cortos.", "it": "Settimana di scarico: volume ridotto, intensità mantenuta su blocchi brevi.", "pt": "Semana mais leve: volume reduzido, intensidade mantida em blocos curtos.", "de": "Entlastung: reduzierter Umfang, Intensität auf kurzen Blöcken beibehalten.", "nl": "Afbouw: minder volume, intensiteit behouden op korte blokken.", "ja": "軽めの週：ボリュームを減らし、短いブロックで強度は維持。", "tr": "Hafifletme: azaltılmış hacim, kısa bloklarda yoğunluk korunuyor."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,5}', '{"fr": "Deuxième cycle : 2×25'' en sweet spot et 2×20'' au seuil. On s''approche de la moitié d''un CLM de 40 km d''un seul tenant.", "en": "Second cycle: 2×25'' at sweet spot and 2×20'' at threshold. We approach half of a 40 km TT in one go.", "es": "Segundo ciclo: 2×25'' en sweet spot y 2×20'' al umbral. Nos acercamos a la mitad de una CRI de 40 km de un solo tirón.", "it": "Secondo ciclo: 2×25'' in sweet spot e 2×20'' in soglia. Ci avviciniamo a metà di una crono di 40 km tutta d''un fiato.", "pt": "Segundo ciclo: 2×25'' em sweet spot e 2×20'' no limiar. Nos aproximamos da metade de um contrarrelógio de 40 km sem pausa.", "de": "Zweiter Zyklus: 2×25'' im Sweet Spot und 2×20'' an der Schwelle. Wir nähern uns der Hälfte eines 40-km-Zeitfahrens am Stück.", "nl": "Tweede cyclus: 2×25'' in sweet spot en 2×20'' op drempel. We naderen de helft van een tijdrit van 40 km aan één stuk.", "ja": "第2サイクル：スイートスポット2×25''と閾値2×20''。40 kmのタイムトライアルの半分を通しで走る時間に近づきます。", "tr": "İkinci döngü: sweet spot''ta 2×25'' ve eşikte 2×20''. 40 km''lik bir zamana karşının yarısına kesintisiz yaklaşıyoruz."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "PMA 5×5'' et 3×20'' au seuil, séparés par du tempo en TT, plus une sortie longue de 2 h.", "en": "VO2max 5×5'' and 3×20'' at threshold, separated by tempo in TT, plus a 2 h long ride.", "es": "VO2max 5×5'' y 3×20'' al umbral, separados por tempo en TT, más una salida larga de 2 h.", "it": "VO2max 5×5'' e 3×20'' in soglia, separati da ritmo tempo in TT, più un''uscita lunga di 2 h.", "pt": "VO2max 5×5'' e 3×20'' no limiar, separados por ritmo tempo em TT, mais um treino longo de 2 h.", "de": "VO2max 5×5'' und 3×20'' an der Schwelle, getrennt durch Tempo in TT, dazu eine lange Fahrt von 2 h.", "nl": "VO2max 5×5'' en 3×20'' op drempel, gescheiden door tempo in TT, plus een lange rit van 2 u.", "ja": "VO2max 5×5''と閾値3×20''、間にTTでのテンポ、さらに2時間のロングライド。", "tr": "VO2max 5×5'' ve eşikte 3×20'', araya TT''de tempo, ayrıca 2 sa uzun sürüş."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,7}', '{"fr": "Pic du deuxième cycle : 60'' d''affilée en sweet spot, sur-sous et 2×30'' au seuil.", "en": "Second-cycle peak: 60'' straight at sweet spot, over-unders and 2×30'' at threshold.", "es": "Pico del segundo ciclo: 60'' seguidos en sweet spot, sobre-bajo y 2×30'' al umbral.", "it": "Picco del secondo ciclo: 60'' di fila in sweet spot, sopra-sotto e 2×30'' in soglia.", "pt": "Pico do segundo ciclo: 60'' seguidos em sweet spot, acima-abaixo e 2×30'' no limiar.", "de": "Höhepunkt des zweiten Zyklus: 60'' am Stück im Sweet Spot, Over-Under und 2×30'' an der Schwelle.", "nl": "Hoogtepunt van de tweede cyclus: 60'' aan één stuk in sweet spot, over-unders en 2×30'' op drempel.", "ja": "第2サイクルのピーク：スイートスポットで60''連続、オーバーアンダー、閾値2×30''。", "tr": "İkinci döngünün zirvesi: sweet spot''ta kesintisiz 60'', üst-altlar ve eşikte 2×30''."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,8}', '{"fr": "Allègement avant le cycle spécifique.", "en": "Lighter week before the specific cycle.", "es": "Semana más ligera antes del ciclo específico.", "it": "Settimana di scarico prima del ciclo specifico.", "pt": "Semana mais leve antes do ciclo específico.", "de": "Entlastung vor dem spezifischen Zyklus.", "nl": "Afbouw voor de specifieke cyclus.", "ja": "特化サイクル前の軽めの週。", "tr": "Özel döngüden önce hafifletme."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,9}', '{"fr": "Cycle spécifique : 2×40'' en sweet spot et 40'' d''affilée au seuil, la première vraie simulation de la course.", "en": "Specific cycle: 2×40'' at sweet spot and 40'' straight at threshold, the first real race simulation.", "es": "Ciclo específico: 2×40'' en sweet spot y 40'' seguidos al umbral, la primera simulación real de la carrera.", "it": "Ciclo specifico: 2×40'' in sweet spot e 40'' di fila in soglia, la prima vera simulazione della gara.", "pt": "Ciclo específico: 2×40'' em sweet spot e 40'' seguidos no limiar, a primeira simulação real da prova.", "de": "Spezifischer Zyklus: 2×40'' im Sweet Spot und 40'' am Stück an der Schwelle, die erste echte Simulation des Rennens.", "nl": "Specifieke cyclus: 2×40'' in sweet spot en 40'' aan één stuk op drempel, de eerste echte simulatie van de wedstrijd.", "ja": "特化サイクル：スイートスポット2×40''と閾値で40''連続、初めての本格的なレースシミュレーション。", "tr": "Özel döngü: sweet spot''ta 2×40'' ve eşikte kesintisiz 40'', yarışın ilk gerçek simülasyonu."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,10}', '{"fr": "75'' d''affilée en sweet spot et 2×30'' à 98 %, une sortie longue de 2 h 20 en TT. L''endurance de position rejoint la durée de la course.", "en": "75'' straight at sweet spot and 2×30'' at 98 %, a 2 h 20 long ride in TT. Your position endurance now matches the race duration.", "es": "75'' seguidos en sweet spot y 2×30'' al 98 %, una salida larga de 2 h 20 en TT. La resistencia en posición alcanza la duración de la carrera.", "it": "75'' di fila in sweet spot e 2×30'' al 98 %, un''uscita lunga di 2 h 20 in TT. La resistenza in posizione raggiunge la durata della gara.", "pt": "75'' seguidos em sweet spot e 2×30'' a 98 %, um treino longo de 2 h 20 em TT. A resistência na posição alcança a duração da prova.", "de": "75'' am Stück im Sweet Spot und 2×30'' bei 98 %, eine lange Fahrt von 2 h 20 in TT. Die Positionsausdauer erreicht die Renndauer.", "nl": "75'' aan één stuk in sweet spot en 2×30'' op 98 %, een lange rit van 2 u 20 in TT. Het uithoudingsvermogen in houding haalt de wedstrijdduur.", "ja": "スイートスポットで75''連続と98 %で2×30''、TTでの2時間20分のロングライド。ポジションの持久力がレースの時間に届きます。", "tr": "Sweet spot''ta kesintisiz 75'' ve %98''de 2×30'', TT''de 2 sa 20 uzun sürüş. Pozisyon dayanıklılığı yarış süresine ulaşıyor."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,11}', '{"fr": "Pic du plan : 2×45'' en sweet spot, puissance critique et 50'' d''affilée à 96 % FTP en TT, l''allure d''un CLM de 40 km.", "en": "Plan peak: 2×45'' at sweet spot, critical power and 50'' straight at 96 % FTP in TT, the pace of a 40 km TT.", "es": "Pico del plan: 2×45'' en sweet spot, potencia crítica y 50'' seguidos al 96 % FTP en TT, el ritmo de una CRI de 40 km.", "it": "Picco del piano: 2×45'' in sweet spot, potenza critica e 50'' di fila al 96 % FTP in TT, il ritmo di una crono di 40 km.", "pt": "Pico do plano: 2×45'' em sweet spot, potência crítica e 50'' seguidos a 96 % FTP em TT, o ritmo de um contrarrelógio de 40 km.", "de": "Höhepunkt des Plans: 2×45'' im Sweet Spot, kritische Leistung und 50'' am Stück bei 96 % FTP in TT, das Tempo eines 40-km-Zeitfahrens.", "nl": "Hoogtepunt van het plan: 2×45'' in sweet spot, kritisch vermogen en 50'' aan één stuk op 96 % FTP in TT, het tempo van een tijdrit van 40 km.", "ja": "プランのピーク：スイートスポット2×45''、クリティカルパワー、TTでFTPの96 %で50''連続、40 kmのタイムトライアルのペースです。", "tr": "Planın zirvesi: sweet spot''ta 2×45'', kritik güç ve TT''de FTP''nin %96''sında kesintisiz 50'', 40 km''lik bir zamana karşının temposu."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,12}', '{"fr": "Affûtage : volume réduit, rappels courts à l''allure de course. Tu arrives frais le jour du CLM.", "en": "Taper: reduced volume, short reminders at race pace. You arrive fresh on TT day.", "es": "Puesta a punto: volumen reducido, recordatorios cortos a ritmo de carrera. Llegas fresco el día de la CRI.", "it": "Scarico: volume ridotto, brevi richiami al ritmo gara. Arrivi fresco il giorno della crono.", "pt": "Polimento: volume reduzido, lembretes curtos no ritmo de prova. Você chega descansado no dia do contrarrelógio.", "de": "Tapering: reduzierter Umfang, kurze Erinnerungsreize im Wettkampftempo. Du gehst frisch ins Zeitfahren.", "nl": "Taperen: minder volume, korte prikkels op wedstrijdtempo. Je komt fris aan de start van de tijdrit.", "ja": "調整（テーパー）：ボリュームを減らし、レースペースで短い刺激を入れます。タイムトライアル当日はフレッシュな状態で臨みます。", "tr": "Yarış öncesi yük azaltma: azaltılmış hacim, yarış temposunda kısa hatırlatmalar. Zamana karşı günü taze geliyorsun."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Adaptation : allure triathlon (85-90 % FTP) en 2×15'' et PMA 4×4'', séparés par du tempo en TT, plus une sortie longue. On installe l''allure de course en TT sur des blocs courts.", "en": "Adaptation: triathlon pace (85-90 % FTP) as 2×15'' and VO2max 4×4'', separated by tempo in TT, plus a long ride. We settle race pace in TT on short blocks.", "es": "Adaptación: ritmo de triatlón (85-90 % FTP) en 2×15'' y VO2max 4×4'', separados por tempo en TT, más una salida larga. Asentamos el ritmo de carrera en TT con bloques cortos.", "it": "Adattamento: ritmo triathlon (85-90 % FTP) in 2×15'' e VO2max 4×4'', separati da ritmo tempo in TT, più un''uscita lunga. Fissiamo il ritmo di gara in TT su blocchi brevi.", "pt": "Adaptação: ritmo de triatlo (85-90 % FTP) em 2×15'' e VO2max 4×4'', separados por ritmo tempo em TT, mais um treino longo. Fixamos o ritmo de prova em TT em blocos curtos.", "de": "Anpassung: Triathlontempo (85-90 % FTP) in 2×15'' und VO2max 4×4'', getrennt durch Tempo in TT, dazu eine lange Fahrt. Du verankerst das Renntempo in TT auf kurzen Blöcken.", "nl": "Aanpassing: triatlontempo (85-90 % FTP) in 2×15'' en VO2max 4×4'', gescheiden door tempo in TT, plus een lange rit. Je legt het wedstrijdtempo in TT vast op korte blokken.", "ja": "適応：トライアスロンペース（FTPの85-90 %）で2×15''とVO2max 4×4''、間にTTでのテンポ、さらにロングライド。短いブロックでTTでのレースペースを定着させます。", "tr": "Uyum: triatlon temposunda (FTP''nin %85-90''ı) 2×15'' ve VO2max 4×4'', araya TT''de tempo, ayrıca bir uzun sürüş. Kısa bloklarla TT''de yarış temposunu yerleştiriyorsun."}'::jsonb) WHERE name_key = 'triathlon_m_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Fin du premier cycle : 3×20'' à l''allure triathlon et PMA 5×4'', du tempo en TT entre les deux, 2 h 15 de sortie longue.", "en": "End of the first cycle: 3×20'' at triathlon pace and VO2max 5×4'', with tempo in TT in between, a 2 h 15 long ride.", "es": "Fin del primer ciclo: 3×20'' a ritmo de triatlón y VO2max 5×4'', con tempo en TT entre ambos, 2 h 15 de salida larga.", "it": "Fine del primo ciclo: 3×20'' al ritmo triathlon e VO2max 5×4'', ritmo tempo in TT nel mezzo, 2 h 15 di uscita lunga.", "pt": "Fim do primeiro ciclo: 3×20'' no ritmo de triatlo e VO2max 5×4'', com ritmo tempo em TT entre os dois, 2 h 15 de treino longo.", "de": "Ende des ersten Zyklus: 3×20'' im Triathlontempo und VO2max 5×4'', Tempo in TT dazwischen, 2 h 15 lange Fahrt.", "nl": "Einde van de eerste cyclus: 3×20'' op triatlontempo en VO2max 5×4'', met tempo in TT ertussen, een lange rit van 2 u 15.", "ja": "第1サイクルの締めくくり：トライアスロンペースで3×20''とVO2max 5×4''、間にTTでのテンポ、2時間15分のロングライド。", "tr": "İlk döngünün sonu: triatlon temposunda 3×20'' ve VO2max 5×4'', arada TT''de tempo, 2 sa 15 uzun sürüş."}'::jsonb) WHERE name_key = 'triathlon_m_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : une seule séance dure, blocs ramenés à 15''. La récupération fait monter la forme avant les blocs longs.", "en": "Lighter week: only one hard session, blocks cut back to 15''. Recovery lifts your form before the long blocks.", "es": "Semana más ligera: una sola sesión dura, bloques reducidos a 15''. La recuperación hace subir la forma antes de los bloques largos.", "it": "Settimana di scarico: una sola seduta dura, blocchi ridotti a 15''. Il recupero fa salire la forma prima dei blocchi lunghi.", "pt": "Semana mais leve: uma única sessão dura, blocos reduzidos a 15''. A recuperação faz a forma subir antes dos blocos longos.", "de": "Entlastung: nur eine harte Einheit, Blöcke auf 15'' verkürzt. Die Erholung hebt die Form vor den langen Blöcken.", "nl": "Afbouw: slechts één zware training, blokken teruggebracht tot 15''. Het herstel brengt de vorm omhoog voor de lange blokken.", "ja": "軽めの週：きついセッションは1回だけ、ブロックは15''に短縮。回復によって長いブロックの前にコンディションが上がります。", "tr": "Hafifletme: sadece bir zor antrenman, bloklar 15''e indirildi. Toparlanma uzun bloklardan önce formu yükseltir."}'::jsonb) WHERE name_key = 'triathlon_m_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "45'' d''affilée à l''allure triathlon et 3×15'' au seuil, du tempo en TT entre les deux. Une position tenue sans crispation laisse des jambes pour courir.", "en": "45'' straight at triathlon pace and 3×15'' at threshold, with tempo in TT in between. A position held without tension leaves legs for the run.", "es": "45'' seguidos a ritmo de triatlón y 3×15'' al umbral, con tempo en TT entre ambos. Una posición mantenida sin crispación deja piernas para correr.", "it": "45'' di fila al ritmo triathlon e 3×15'' in soglia, ritmo tempo in TT nel mezzo. Una posizione tenuta senza contrazioni lascia gambe per correre.", "pt": "45'' seguidos no ritmo de triatlo e 3×15'' no limiar, com ritmo tempo em TT entre os dois. Uma posição sustentada sem tensão deixa pernas para correr.", "de": "45'' am Stück im Triathlontempo und 3×15'' an der Schwelle, Tempo in TT dazwischen. Eine Position, die du ohne Verkrampfung hältst, lässt Beine fürs Laufen übrig.", "nl": "45'' aan één stuk op triatlontempo en 3×15'' op drempel, met tempo in TT ertussen. Een houding die je zonder verkramping vasthoudt, laat benen over om te lopen.", "ja": "トライアスロンペースで45''連続と閾値3×15''、間にTTでのテンポ。力まずに保てるポジションなら、ランのための脚が残ります。", "tr": "Triatlon temposunda kesintisiz 45'' ve eşikte 3×15'', arada TT''de tempo. Kasılmadan tutulan bir pozisyon koşu için bacak bırakır."}'::jsonb) WHERE name_key = 'triathlon_m_8w_name';
